1	import * as fs from "node:fs";
2	import * as path from "node:path";
3	import { createHash } from "node:crypto";
4	import { redactSecrets } from "../ui.js";
5	import type { RunManifest, RunStatus } from "./contracts.js";
6	
7	export interface IntegrityRecord {
8	  runId: string;
9	  calculatedAt: string;
10	  fileHashes: Record<string, string>;
11	  compositeSha256: string;
12	  migrated?: boolean;
13	  migratedAt?: string;
14	  migrationReason?: string;
15	  normalizedAssertions?: string[];
16	}
17	
18	export type IntegrityFailureReason =
19	  | "INTEGRITY_MISSING"
20	  | "INTEGRITY_UNREADABLE"
21	  | "RUN_ID_MISMATCH"
22	  | "FILE_SET_MISMATCH"
23	  | "HASH_MISMATCH"
24	  | "COMPOSITE_MISMATCH"
25	  | "NON_BOOLEAN_PASSED";
26	
27	export class CeriEvidenceIntegrityError extends Error {
28	  constructor(readonly reason: IntegrityFailureReason, detail: string) {
29	    super(`CERI evidence rejected (${reason}): ${detail}`);
30	    this.name = "CeriEvidenceIntegrityError";
31	  }
32	}
33	
34	function compositeOf(fileHashes: Record<string, string>): string {
35	  const hasher = createHash("sha256");
36	  for (const file of Object.keys(fileHashes).sort()) hasher.update(`${file}:${fileHashes[file]};`);
37	  return hasher.digest("hex");
38	}
39	
40	export function sanitizeIdentifier(id: string, name: string): string {
41	  if (!id || typeof id !== "string") {
42	    throw new Error(`Invalid ${name}: must be a non-empty string`);
43	  }
44	  const trimmed = id.trim();
45	  if (
46	    trimmed === "." ||
47	    trimmed.includes("..") ||
48	    trimmed.includes("/") ||
49	    trimmed.includes("\\") ||
50	    !/^[a-zA-Z0-9_.-]+$/.test(trimmed)
51	  ) {
52	    throw new Error(
53	      `Invalid ${name} "${id}": contains invalid characters or path traversal elements`
54	    );
55	  }
56	  return trimmed;
57	}
58	
59	/** Words that make a key a credential on their own. */
60	const SECRET_WORDS = new Set([
61	  "password", "passwords", "passwd", "passphrase", "pwd", "secret", "secrets", "credential", "credentials", "authorization", "auth", "cookie", "cookies", "bearer", "jwt", "apikey",
62	  // The same names written as one lowercase word.
63	  "accesstoken", "refreshtoken", "idtoken", "authtoken", "sessiontoken", "bearertoken", "apitoken", "clientsecret",
64	  "secretvalue",
65	]);
66	/** Words that, before "pass", make it a password (`DB_PASS`, `user_pass`); bare `pass` and `bypass` are not credentials. */
67	const PASS_CONTEXT = new Set(["db", "database", "user", "admin", "root", "login", "smtp", "mysql", "postgres", "redis", "ssh", "ftp", "sql", "mongo", "ldap", "wifi", "master"]);
68	/** Words after "token" that make it a count or a limit (`tokenCount`, `token_limit`). */
69	const COUNT_AFTER = new Set(["count", "counts", "limit", "limits", "budget", "usage", "total", "used"]);
70	/** Words that, before "token", make it a count or a limit rather than a credential. */
71	const COUNT_WORDS = new Set(["max", "min", "total", "input", "output", "prompt", "completion", "num", "count", "context", "reasoning", "cached", "budget"]);
72	
73	/** Words before a bare `pat` that make it a personal access token (`github_pat`, `user_pat`). */
74	const PAT_OWNERS = new Set(["github", "gitlab", "gh", "user", "personal", "access", "my", "bitbucket", "azure"]);
75	/** Words that, before `key`, make it a credential (`api_key`, `ssh_keys`). */
76	const KEY_CONTEXT = new Set(["api", "access", "private", "secret", "auth", "signing", "ssh", "master", "encryption"]);
77	/** Words after `key` that make it a reference to a key, not the key (`encryptionKeyId`, `api_key_name`). */
78	const KEY_REFERENCE = new Set(["id", "ids", "name", "names", "path", "file", "fingerprint", "type", "version", "ref", "label"]);
79	
80	/** Splits `apiKey`, `api_key`, `api-key` and `X-Api-Key` into lowercase words. */
81	function keyWords(key: string): string[] {
82	  return key
83	    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
84	    .split(/[^A-Za-z0-9]+/)
85	    .filter(Boolean)
86	    .map((w) => w.toLowerCase());
87	}
88	
89	/** `dbpass`, `sshkey` and `encryptionkeys` written as one lowercase word: a context word from the lists above plus `pass` or `key(s)`. */
90	function isJoinedCredentialWord(w: string): boolean {
91	  for (const p of PASS_CONTEXT) if (w === `${p}pass`) return true;
92	  for (const p of KEY_CONTEXT) if (w === `${p}key` || w === `${p}keys`) return true;
93	  return false;
94	}
95	
96	/** Whether a key names a credential, by whole words: `api_key` and `access_token` do, `max_token`, `pass` and `bypass` do not. */
97	export function isSensitiveKey(key: string): boolean {
98	  const words = keyWords(key);
99	  return words.some((w, i) => {
100	    if (SECRET_WORDS.has(w) || isJoinedCredentialWord(w)) return true;
101	    if (w === "token") return !COUNT_WORDS.has(words[i - 1] ?? "") && !COUNT_AFTER.has(words[i + 1] ?? "");
102	    if (w === "pass") return PASS_CONTEXT.has(words[i - 1] ?? "") || ["word", "wd", "phrase"].includes(words[i + 1] ?? "");
103	    // `pat` is a personal access token only alone or after a provider or owner word, so `path_pat` (a pattern) is kept.
104	    if (w === "pat") return words.length === 1 || PAT_OWNERS.has(words[i - 1] ?? "");
105	    // `key` and `keys` after a credential word; `encryptionKeyId` and `keyName` only name a key, so they are kept.
106	    if (w === "key" || w === "keys") return KEY_CONTEXT.has(words[i - 1] ?? "") && !KEY_REFERENCE.has(words[i + 1] ?? "");
107	    return false;
108	  });
109	}
110	
111	/**
112	 * Serializes evidence with secrets removed. A replacer that only sees string values cannot know that
113	 * `{"apiKey": "abcdef1234567890"}` is a credential, so the key name is checked as well as the value text, and the
114	 * whole value under a credential key (string, number, array or object) is replaced.
115	 */
116	function redactedJson(data: unknown, space?: number): string {
117	  return JSON.stringify(
118	    data,
119	    (key, v) => {
120	      if (key && v !== null && v !== undefined && isSensitiveKey(key)) return "[REDACTED]";
121	      return typeof v === "string" ? redactSecrets(v) : v;
122	    },
123	    space,
124	  );
125	}
126	
127	export class CeriEvidenceStore {
128	  private readonly baseDir: string;
129	  private currentRunDir?: string;
130	  private currentManifest?: RunManifest;
131	
132	  constructor(baseDir: string) {
133	    this.baseDir = path.resolve(baseDir);
134	    if (!fs.existsSync(this.baseDir)) {
135	      fs.mkdirSync(this.baseDir, { recursive: true });
136	    }
137	  }
138	
139	  /**
140	   * Initializes a run directory and atomically writes the initial RunManifest.
141	   */
142	  initRun(manifest: RunManifest): string {
143	    const sEvalId = sanitizeIdentifier(manifest.evaluationId, "evaluationId");
144	    const sRunId = sanitizeIdentifier(manifest.runId, "runId");
145	    const runDir = path.resolve(this.baseDir, sEvalId, sRunId);
146	    if (!runDir.startsWith(this.baseDir + path.sep)) {
147	      throw new Error(`Path traversal detected: ${runDir} is outside baseDir ${this.baseDir}`);
148	    }
149	
150	    fs.mkdirSync(path.dirname(runDir), { recursive: true });
151	    try {
152	      fs.mkdirSync(runDir);
153	    } catch (err) {
154	      if ((err as NodeJS.ErrnoException).code === "EEXIST") {
155	        throw new Error(
156	          `Run "${sRunId}" already exists for evaluation "${sEvalId}"; run ids are never reused or overwritten. ` +
157	            `If that run crashed before finalizeRun, quarantine it with abandonRun("${sEvalId}", "${sRunId}") and start again.`,
158	        );
159	      }
160	      throw err;
161	    }
162	    this.currentRunDir = runDir;
163	    this.currentManifest = { ...manifest, status: "RUNNING" };
164	
165	    const manifestPath = path.join(runDir, "manifest.json");
166	    this.atomicWriteJson(manifestPath, this.currentManifest);
167	    return runDir;
168	  }
169	
170	  /**
171	   * Appends an event to events.jsonl with secret redaction.
172	   */
173	  appendEvent(event: Record<string, unknown>): void {
174	    if (!this.currentRunDir) {
175	      throw new Error("Cannot append event: no active run initialized");
176	    }
177	    const eventsPath = path.join(this.currentRunDir, "events.jsonl");
178	    const serialized = redactedJson(event);
179	    fs.appendFileSync(eventsPath, serialized + "\n", { encoding: "utf-8" });
180	  }
181	
182	  /**
183	   * Records deterministic assertion outputs atomically.
184	   */
185	  recordAssertions(assertions: Record<string, unknown>[]): void {
186	    if (!this.currentRunDir) {
187	      throw new Error("Cannot record assertions: no active run initialized");
188	    }
189	    const assertionsPath = path.join(this.currentRunDir, "assertions.json");
190	    this.atomicWriteJson(assertionsPath, assertions);
191	  }
192	
193	  /**
194	   * Records independent validation receipts atomically.
195	   */
196	  recordReceipts(receipts: Record<string, unknown>[]): void {
197	    if (!this.currentRunDir) {
198	      throw new Error("Cannot record receipts: no active run initialized");
199	    }
200	    const receiptsPath = path.join(this.currentRunDir, "receipts.json");
201	    this.atomicWriteJson(receiptsPath, receipts);
202	  }
203	
204	  /**
205	   * Finalizes the run, updates status and completedAt in manifest, and generates
206	   * a tamper-evident integrity record linking all artifacts.
207	   */
208	  finalizeRun(status: RunStatus, terminationReason?: string): { integrityHash: string; runDir: string } {
209	    if (!this.currentRunDir || !this.currentManifest) {
210	      throw new Error("Cannot finalize run: no active run initialized");
211	    }
212	
213	    const completedAt = new Date().toISOString();
214	    const durationMs = Date.now() - new Date(this.currentManifest.startedAt).getTime();
215	
216	    this.currentManifest.status = status;
217	    this.currentManifest.completedAt = completedAt;
218	    this.currentManifest.durationMs = durationMs;
219	    if (terminationReason) {
220	      this.currentManifest.terminationReason = terminationReason;
221	    }
222	
223	    const manifestPath = path.join(this.currentRunDir, "manifest.json");
224	    this.atomicWriteJson(manifestPath, this.currentManifest);
225	
226	    const compositeSha256 = this.writeIntegrity(this.currentRunDir, this.currentManifest.runId, completedAt);
227	
228	    const result = { integrityHash: compositeSha256, runDir: this.currentRunDir };
229	    this.currentRunDir = undefined;
230	    this.currentManifest = undefined;
231	    return result;
232	  }
233	
234	  private runDirOf(evaluationId: string, runId: string): { sEvalId: string; sRunId: string; runDir: string } {
235	    const sEvalId = sanitizeIdentifier(evaluationId, "evaluationId");
236	    const sRunId = sanitizeIdentifier(runId, "runId");
237	    const runDir = path.resolve(this.baseDir, sEvalId, sRunId);
238	    if (!runDir.startsWith(this.baseDir + path.sep)) {
239	      throw new Error(`Path traversal detected: ${runDir} is outside baseDir ${this.baseDir}`);
240	    }
241	    return { sEvalId, sRunId, runDir };
242	  }
243	
244	  /** Reads every evidence file of a run once (regular files only); the same buffers are hashed and parsed. */
245	  private readRunFiles(runDir: string): Map<string, Buffer> | string {
246	    const files = new Map<string, Buffer>();
247	    for (const name of fs.readdirSync(runDir).sort()) {
248	      if (name === "integrity.json" || name.startsWith(".tmp")) continue;
249	      const full = path.join(runDir, name);
250	      if (!fs.lstatSync(full).isFile()) return `'${name}' is not a regular file`;
251	      files.set(name, fs.readFileSync(full));
252	    }
253	    return files;
254	  }
255	
256	  private writeIntegrity(runDir: string, runId: string, calculatedAt: string, extra: Partial<IntegrityRecord> = {}): string {
257	    const files = this.readRunFiles(runDir);
258	    if (typeof files === "string") throw new Error(`Cannot write integrity record: ${files}`);
259	    const fileHashes: Record<string, string> = {};
260	    for (const [name, buf] of files) fileHashes[name] = createHash("sha256").update(buf).digest("hex");
261	    const compositeSha256 = compositeOf(fileHashes);
262	    const record: IntegrityRecord = { runId, calculatedAt, fileHashes, compositeSha256, ...extra };
263	    this.atomicWriteJson(path.join(runDir, "integrity.json"), record, false);
264	    return compositeSha256;
265	  }
266	
267	  private verifyAndRead(
268	    sEvalId: string,
269	    sRunId: string,
270	    runDir: string,
271	  ): { ok: true; files: Map<string, Buffer>; migrated: boolean } | { ok: false; reason: IntegrityFailureReason; detail: string } {
272	    const fail = (reason: IntegrityFailureReason, detail: string) => ({ ok: false as const, reason, detail });
273	    const integrityPath = path.join(runDir, "integrity.json");
274	    if (!fs.existsSync(integrityPath)) {
275	      return fail(
276	        "INTEGRITY_MISSING",
277	        `no integrity record for run '${sRunId}'. If the run crashed before finalizeRun, quarantine it with abandonRun; ` +
278	          `for evidence written before integrity records existed, an operator can run migrateLegacyRun`,
279	      );
280	    }
281	    const legacy = ` (legacy evidence can be re-recorded by an operator with migrateLegacyRun("${sEvalId}", "${sRunId}", reason))`;
282	    let record: IntegrityRecord;
283	    try {
284	      record = JSON.parse(fs.readFileSync(integrityPath, "utf-8")) as IntegrityRecord;
285	      if (!record || typeof record.fileHashes !== "object" || record.fileHashes === null || typeof record.compositeSha256 !== "string") throw new Error("bad shape");
286	    } catch {
287	      return fail("INTEGRITY_UNREADABLE", `integrity.json is not a valid integrity record${legacy}`);
288	    }
289	    if (record.runId !== sRunId) return fail("RUN_ID_MISMATCH", `record names run '${record.runId}', directory is '${sRunId}'${legacy}`);
290	    const files = this.readRunFiles(runDir);
291	    if (typeof files === "string") return fail("FILE_SET_MISMATCH", files);
292	    const recorded = Object.keys(record.fileHashes).sort();
293	    const present = [...files.keys()];
294	    if (present.join("\0") !== recorded.join("\0")) return fail("FILE_SET_MISMATCH", `files on disk [${present}] differ from recorded [${recorded}]${legacy}`);
295	    for (const [name, buf] of files) {
296	      if (createHash("sha256").update(buf).digest("hex") !== record.fileHashes[name]) return fail("HASH_MISMATCH", `${name} does not match its recorded hash${legacy}`);
297	    }
298	    if (compositeOf(record.fileHashes) !== record.compositeSha256) return fail("COMPOSITE_MISMATCH", `composite hash does not match the recorded file hashes${legacy}`);
299	    return { ok: true, files, migrated: record.migrated === true };
300	  }
301	
302	  /**
303	   * Checks a run's integrity record against the files on disk: record present and readable, naming this run, covering
304	   * exactly the regular files present, with every file hash and the composite matching.
305	   */
306	  verifyRun(evaluationId: string, runId: string): { ok: true; migrated?: true } | { ok: false; reason: IntegrityFailureReason; detail: string } {
307	    const { sEvalId, sRunId, runDir } = this.runDirOf(evaluationId, runId);
308	    const v = this.verifyAndRead(sEvalId, sRunId, runDir);
309	    if (!v.ok) return v;
310	    return v.migrated ? { ok: true, migrated: true } : { ok: true };
311	  }
312	
313	  /** Verified evidence files of a run, or undefined when the run does not exist. Throws on any integrity failure. */
314	  private loadVerifiedFile(evaluationId: string, runId: string, file: string): Buffer | undefined {
315	    const { sEvalId, sRunId, runDir } = this.runDirOf(evaluationId, runId);
316	    if (!fs.existsSync(runDir)) return undefined;
317	    const v = this.verifyAndRead(sEvalId, sRunId, runDir);
318	    if (!v.ok) throw new CeriEvidenceIntegrityError(v.reason, v.detail);
319	    return v.files.get(file);
320	  }
321	
322	  /**
323	   * Quarantines a run that never reached finalizeRun (a crash): the directory is renamed to `<id>.abandoned-<ms>`,
324	   * never deleted, and the run id becomes available again. A finalized run cannot be abandoned.
325	   */
326	  abandonRun(evaluationId: string, runId: string): string {
327	    const { sRunId, runDir } = this.runDirOf(evaluationId, runId);
328	    if (!fs.existsSync(runDir)) throw new Error(`Cannot abandon: no run '${sRunId}' for evaluation '${evaluationId}'`);
329	    if (fs.existsSync(path.join(runDir, "integrity.json"))) throw new Error(`Cannot abandon run '${sRunId}': it is finalized`);
330	    const target = `${runDir}.abandoned-${Date.now()}`;
331	    fs.renameSync(runDir, target);
332	    if (this.currentRunDir === runDir) {
333	      this.currentRunDir = undefined;
334	      this.currentManifest = undefined;
335	    }
336	    return target;
337	  }
338	
339	  /**
340	   * One-way, operator-invoked re-recording of evidence written before integrity records were reliable (missing,
341	   * redacted or mismatched record, string `passed`). The old integrity record and any rewritten assertions file are kept
342	   * as `*.pre-migration-<ms>.*`; the new record is marked `migrated` with the reason. Only the exact strings "true" and
343	   * "false" are normalized; anything else is refused. A run that already verifies is not migrated. This trusts the files
344	   * as they are now: it records, it does not prove, that they are the original evidence.
345	   */
346	  migrateLegacyRun(evaluationId: string, runId: string, reason: string): { integrityHash: string; runDir: string } {
347	    if (typeof reason !== "string" || !reason.trim()) throw new Error("migrateLegacyRun requires a non-empty reason");
348	    const { sEvalId, sRunId, runDir } = this.runDirOf(evaluationId, runId);
349	    if (!fs.existsSync(runDir)) throw new Error(`Cannot migrate: no run '${sRunId}' for evaluation '${sEvalId}'`);
350	    const stamp = Date.now();
351	    const files = this.readRunFiles(runDir);
352	    if (typeof files === "string") throw new Error(`Cannot migrate run '${sRunId}': ${files}`);
353	    if (this.verifyAndRead(sEvalId, sRunId, runDir).ok) throw new Error(`Run '${sRunId}' already verifies; nothing to migrate`);
354	
355	    const normalized: string[] = [];
356	    let rewritten: string | undefined;
357	    const raw = files.get("assertions.json");
358	    if (raw) {
359	      let data: unknown;
360	      try {
361	        data = JSON.parse(raw.toString("utf-8"));
362	      } catch {
363	        data = undefined;
364	      }
365	      const fix = (id: string, passed: unknown): boolean => {
366	        if (typeof passed === "boolean") return passed;
367	        if (passed === "true" || passed === "false") {
368	          normalized.push(id);
369	          return passed === "true";
370	        }
371	        throw new CeriEvidenceIntegrityError("NON_BOOLEAN_PASSED", `assertion '${id}' has passed=${JSON.stringify(passed)}, cannot be migrated`);
372	      };
373	      if (Array.isArray(data)) {
374	        rewritten = JSON.stringify(data.map((i) => (i && typeof i === "object" && typeof i.id === "string" ? { ...i, passed: fix(i.id, i.passed) } : i)), null, 2);
375	      } else if (data && typeof data === "object") {
376	        rewritten = JSON.stringify(Object.fromEntries(Object.entries(data).map(([id, p]) => [id, fix(id, p)])), null, 2);
377	      }
378	    }
379	    if (rewritten !== undefined && normalized.length > 0) {
380	      fs.renameSync(path.join(runDir, "assertions.json"), path.join(runDir, `assertions.pre-migration-${stamp}.json`));
381	      fs.writeFileSync(path.join(runDir, "assertions.json"), rewritten, "utf-8");
382	    }
383	    const integrityPath = path.join(runDir, "integrity.json");
384	    if (fs.existsSync(integrityPath)) fs.renameSync(integrityPath, path.join(runDir, `integrity.pre-migration-${stamp}.json`));
385	    const integrityHash = this.writeIntegrity(runDir, sRunId, new Date(stamp).toISOString(), {
386	      migrated: true,
387	      migratedAt: new Date(stamp).toISOString(),
388	      migrationReason: reason.trim(),
389	      normalizedAssertions: normalized,
390	    });
391	    return { integrityHash, runDir };
392	  }
393	
394	  /**
395	   * Loads assertions recorded for a past evaluation run.
396	   */
397	  loadAssertions(evaluationId: string, runId: string): Record<string, boolean> | undefined {
398	    const raw = this.loadVerifiedFile(evaluationId, runId, "assertions.json");
399	    if (!raw) return undefined;
400	    let data: unknown;
401	    try {
402	      data = JSON.parse(raw.toString("utf-8"));
403	    } catch {
404	      return undefined;
405	    }
406	    const strict = (id: string, passed: unknown): boolean => {
407	      if (typeof passed !== "boolean") {
408	        throw new CeriEvidenceIntegrityError("NON_BOOLEAN_PASSED", `assertion '${id}' has passed=${JSON.stringify(passed)}, expected a boolean`);
409	      }
410	      return passed;
411	    };
412	    const map: Record<string, boolean> = {};
413	    if (Array.isArray(data)) {
414	      for (const item of data) {
415	        if (item && typeof item === "object" && typeof item.id === "string") map[item.id] = strict(item.id, item.passed);
416	      }
417	      return map;
418	    }
419	    if (data && typeof data === "object") {
420	      for (const [id, passed] of Object.entries(data)) map[id] = strict(id, passed);
421	      return map;
422	    }
423	    return undefined;
424	  }
425	
426	  /**
427	   * Loads manifest for a past evaluation run.
428	   */
429	  loadManifest(evaluationId: string, runId: string): RunManifest | undefined {
430	    const raw = this.loadVerifiedFile(evaluationId, runId, "manifest.json");
431	    if (!raw) return undefined;
432	    try {
433	      return JSON.parse(raw.toString("utf-8")) as RunManifest;
434	    } catch {
435	      return undefined;
436	    }
437	  }
438	
439	  /**
440	   * Scans baseDir for runs left in RUNNING status without completion (interrupted runs).
441	   */
442	  detectInterruptedRuns(): string[] {
443	    const interrupted: string[] = [];
444	    if (!fs.existsSync(this.baseDir)) return interrupted;
445	
446	    const evalDirs = fs.readdirSync(this.baseDir);
447	    for (const evalId of evalDirs) {
448	      const evalPath = path.join(this.baseDir, evalId);
449	      if (!fs.statSync(evalPath).isDirectory()) continue;
450	
451	      const runDirs = fs.readdirSync(evalPath);
452	      for (const runId of runDirs) {
453	        if (runId.includes(".abandoned-")) continue;
454	        const runPath = path.join(evalPath, runId);
455	        if (!fs.statSync(runPath).isDirectory()) continue;
456	
457	        const manifestPath = path.join(runPath, "manifest.json");
458	        if (fs.existsSync(manifestPath)) {
459	          try {
460	            const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf-8")) as RunManifest;
461	            if (manifest.status === "RUNNING" && !manifest.completedAt) {
462	              interrupted.push(manifest.runId);
463	            }
464	          } catch {}
465	        }
466	      }
467	    }
468	    return interrupted;
469	  }
470	
471	  /**
472	   * Atomically writes JSON content via temporary file rename.
473	   */
474	  private atomicWriteJson(targetPath: string, data: unknown, redact = true): void {
475	    const dir = path.dirname(targetPath);
476	    const tmpPath = path.join(dir, `.tmp.${path.basename(targetPath)}.${process.pid}.${Date.now()}`);
477	    const serialized = redact ? redactedJson(data, 2) : JSON.stringify(data, null, 2);
478	
