52	  /**
53	   * Builds a baseline specification whose identity and manifest hash are taken from the baseline run's own manifest.
54	   * Call it on the FINALIZED manifest as stored (e.g. `store.loadManifest`), not an in-flight one: a RUNNING manifest is
55	   * refused because its hash would change at finalization.
56	   */
57	  static bindBaseline(
58	    manifest: RunManifest,
59	    fields: { baselineId: string; selectionRationale: string; establishedAt: string; assertions?: Record<string, boolean> }
60	  ): BaselineSpecification {
61	    if (manifest.status !== "COMPLETED" && manifest.status !== "FAILED") {
62	      throw new Error(`Cannot bind a baseline to a run that is not finished (status '${manifest.status}')`);
63	    }
64	    const identity = this.identityOf(manifest);
65	    return {
66	      ...fields,
67	      evaluationId: manifest.evaluationId,
68	      evaluationVersion: manifest.evaluationVersion,
69	      sourceCommit: manifest.sourceCommit,
70	      modelName: manifest.model.name,
71	      modelQuantization: manifest.model.quantization,
72	      manifestSha256: identity.manifestSha256,
73	      identity,
74	    };
75	  }
76	
77	  /**
78	   * IDENTITY_BOUND only when the baseline identity is recorded with a well-formed manifest hash, the baseline manifest is
79	   * supplied and verified, model digests and sampling temperature are recorded on both sides, and digest, sampling,
80	   * configuration, evaluator and tool versions all match. Otherwise UNBOUND, with reasons.
81	   * Local, unsigned identity binding; not external qualification; an attacker who edits manifest, hash and identity
82	   * together passes.
83	   */
84	  private static bindIdentity(
85	    manifest: RunManifest,
86	    baseline: BaselineSpecification,
87	    baselineManifest: RunManifest | undefined
88	  ): NonNullable<BaselineComparisonResult["identityBinding"]> {
89	    const currentIdentity = this.identityOf(manifest);
90	    const reasons: string[] = [];
91	    const bound = baseline.identity;
92	    const unbound = (why: string) => reasons.push(`BASELINE_IDENTITY_UNBOUND: ${why}`);
93	    if (!SHA256_HEX.test(baseline.manifestSha256 ?? "")) unbound("manifestSha256 is not a sha256 hex digest");
94	    if (!bound) unbound("baseline identity not recorded");
95	    else if (!baselineManifest) reasons.push("baseline manifest not supplied; baseline identity unverified");
96	    if (bound) {
97	      const baseSampling = normalizeSampling(bound.sampling);
98	      const curSampling = currentIdentity.sampling;
99	      if (!MODEL_DIGEST.test(bound.model.digest ?? "")) reasons.push("baseline model digest not recorded or malformed");
100	      if (!MODEL_DIGEST.test(currentIdentity.model.digest ?? "")) reasons.push("current model digest not recorded or malformed");
101	      if (typeof baseSampling.temperature !== "number") reasons.push("baseline sampling temperature not recorded");
102	      if (typeof curSampling.temperature !== "number") reasons.push("current sampling temperature not recorded");
103	      const diffs: Array<[string, unknown, unknown]> = [
104	        ["model digest", bound.model.digest, currentIdentity.model.digest],
105	        ["sampling parameters", baseSampling, curSampling],
106	        ["configuration", bound.configurationSha256, currentIdentity.configurationSha256],
107	        ["evaluator version", bound.evaluatorVersion, currentIdentity.evaluatorVersion],
108	        ["toolchain versions", bound.toolchainVersions, currentIdentity.toolchainVersions],
109	      ];
110	      for (const [name, b, c] of diffs) {
111	        if (canonicalJson(b) !== canonicalJson(c)) reasons.push(`${name} differ between baseline and current run`);
112	      }
113	    }
114	    return {
115	      status: reasons.length === 0 ? "IDENTITY_BOUND" : "UNBOUND",
116	      reasons,
117	      baselineIdentity: bound,
118	      currentIdentity,
119	    };
120	  }
121	
122	  /**
123	   * Checks whether a run is eligible for direct comparison against a designated baseline.
124	   */
125	  static checkComparability(
126	    manifest: RunManifest,
127	    baseline: BaselineSpecification
128	  ): { eligible: boolean; reasons: string[] } {
129	    const reasons: string[] = [];
130	
131	    if (manifest.evaluationId !== baseline.evaluationId) {
132	      reasons.push(
133	        `Evaluation ID mismatch: current '${manifest.evaluationId}' vs baseline '${baseline.evaluationId}'`
134	      );
135	    }
136	
137	    if (manifest.evaluationVersion !== baseline.evaluationVersion) {
138	      reasons.push(
139	        `Evaluation definition version drift: current '${manifest.evaluationVersion}' vs baseline '${baseline.evaluationVersion}'`
140	      );
141	    }
142	
143	    if (manifest.model.name !== baseline.modelName) {
144	      reasons.push(
145	        `Model mismatch: current '${manifest.model.name}' vs baseline '${baseline.modelName}'`
146	      );
147	    }
148	
149	    // Absent on one side is a mismatch: comparability cannot be established without matching configurations.
150	    const currentQuantization = manifest.model.quantization || undefined;
151	    const baselineQuantization = baseline.modelQuantization || undefined;
152	    if (currentQuantization !== baselineQuantization) {
153	      reasons.push(
154	        `Model quantization mismatch: current '${currentQuantization ?? "(unrecorded)"}' vs baseline '${baselineQuantization ?? "(unrecorded)"}'`
155	      );
156	    }
157	
158	    if (manifest.dirtyWorktree) {
159	      reasons.push("Current run was executed on an uncommitted / dirty worktree");
160	    }
161	
162	    return {
163	      eligible: reasons.length === 0,
164	      reasons,
165	    };
166	  }
167	
168	  /**
169	   * Evaluates current run assertions against baseline assertions and classifies the comparative outcome
170	   * into one of 12 distinct deterministic states.
171	   */
172	  static compareRuns(
173	    manifest: RunManifest,
174	    currentAssertions: Record<string, boolean>,
175	    baseline: BaselineSpecification,
176	    baselineAssertions: Record<string, boolean>,
177	    isRepeatReproduction = false,
178	    options?: { isPriorRegressionCandidate?: boolean; isKnownFlaky?: boolean; baselineManifest?: RunManifest }
179	  ): BaselineComparisonResult {
180	    const identityBinding = this.bindIdentity(manifest, baseline, options?.baselineManifest);
181	    const tampered: string[] = [];
182	    if (options?.baselineManifest && SHA256_HEX.test(baseline.manifestSha256 ?? "")) {
183	      if (this.manifestSha256(options.baselineManifest) !== baseline.manifestSha256) {
184	        tampered.push("BASELINE_MANIFEST_MISMATCH: the supplied baseline manifest does not match the recorded manifestSha256");
185	      }
186	      if (baseline.identity && canonicalJson(baseline.identity) !== canonicalJson(this.identityOf(options.baselineManifest))) {
187	        tampered.push("BASELINE_IDENTITY_MISMATCH: the recorded baseline identity does not match the baseline manifest");
188	      }
189	    }
190	    if (tampered.length > 0) {
191	      return {
192	        baselineId: baseline.baselineId,
193	        currentRunId: manifest.runId,
194	        isEligibleForComparison: false,
195	        incomparabilityReasons: tampered,
196	        outcome: "INCOMPARABLE",
197	        divergences: [],
198	        confidence: 0.0,
199	        explanation: `Baseline is not the one that was recorded: ${tampered.join("; ")}`,
200	        identityBinding: { ...identityBinding, status: "UNBOUND", reasons: [...tampered, ...identityBinding.reasons] },
201	      };
202	    }
203	    return { ...this.classifyRuns(manifest, currentAssertions, baseline, baselineAssertions, isRepeatReproduction, options), identityBinding };
204	  }
205	
206	  private static classifyRuns(
207	    manifest: RunManifest,
208	    currentAssertions: Record<string, boolean>,
209	    baseline: BaselineSpecification,
210	    baselineAssertions: Record<string, boolean>,
211	    isRepeatReproduction: boolean,
212	    options?: { isPriorRegressionCandidate?: boolean; isKnownFlaky?: boolean }
213	  ): BaselineComparisonResult {
214	    // 1. Check basic execution statuses and failure types
215	    if (manifest.status === "CANCELLED") {
216	      return {
217	        baselineId: baseline.baselineId,
218	        currentRunId: manifest.runId,
219	        isEligibleForComparison: false,
220	        outcome: "CANCELLED",
221	        divergences: [],
222	        confidence: 1.0,
223	        explanation: "Run was cancelled by operator before completion.",
224	      };
225	    }
226	
227	    if (manifest.status === "INTERRUPTED" || manifest.status === "INCONCLUSIVE") {
228	      return {
229	        baselineId: baseline.baselineId,
230	        currentRunId: manifest.runId,
231	        isEligibleForComparison: false,
232	        outcome: "INCONCLUSIVE",
233	        divergences: [],
234	        confidence: 0.0,
235	        explanation:
236	          manifest.terminationReason ??
237	          "Run was inconclusive or interrupted before assertions could be finalized.",
238	      };
239	    }
240	
241	    if (manifest.status === "NOT_EXECUTED") {
242	      return {
243	        baselineId: baseline.baselineId,
244	        currentRunId: manifest.runId,
245	        isEligibleForComparison: false,
246	        outcome: "NOT_EXECUTED",
247	        divergences: [],
248	        confidence: 1.0,
249	        explanation: "Run was scheduled or created but not executed.",
250	      };
251	    }
252	
253	    if (
254	      manifest.status === "INFRASTRUCTURE_FAILURE" ||
255	      manifest.terminationReason?.toLowerCase().includes("infrastructure")
256	    ) {
257	      return {
258	        baselineId: baseline.baselineId,
259	        currentRunId: manifest.runId,
260	        isEligibleForComparison: false,
261	        outcome: "INFRASTRUCTURE_FAILURE",
262	        divergences: [],
263	        confidence: 1.0,
264	        explanation:
265	          manifest.terminationReason ??
266	          "Run failed due to infrastructure or environment failure.",
267	      };
268	    }
269	
270	    if (
271	      manifest.status === "EVALUATOR_DEFECT" ||
272	      manifest.terminationReason?.toLowerCase().includes("evaluator defect")
273	    ) {
274	      return {
275	        baselineId: baseline.baselineId,
276	        currentRunId: manifest.runId,
277	        isEligibleForComparison: false,
278	        outcome: "EVALUATOR_DEFECT",
279	        divergences: [],
280	        confidence: 1.0,
281	        explanation:
282	          manifest.terminationReason ??
283	          "Run failed due to defect in assertion evaluation harness or specification.",
284	      };
285	    }
286	
287	    if (manifest.status !== "COMPLETED" && manifest.status !== "FAILED") {
288	      return {
289	        baselineId: baseline.baselineId,
290	        currentRunId: manifest.runId,
291	        isEligibleForComparison: false,
292	        outcome: "INCONCLUSIVE",
293	        divergences: [],
294	        confidence: 0.0,
295	        explanation: `Run status '${String(manifest.status)}' is not a finished execution; nothing to compare.`,
296	      };
297	    }
298	
299	    // 2. Check baseline comparability
300	    const comp = this.checkComparability(manifest, baseline);
301	    if (!comp.eligible) {
302	      return {
303	        baselineId: baseline.baselineId,
304	        currentRunId: manifest.runId,
305	        isEligibleForComparison: false,
306	        incomparabilityReasons: comp.reasons,
307	        outcome: "INCOMPARABLE",
308	        divergences: [],
309	        confidence: 0.0,
310	        explanation: `Incomparable configurations: ${comp.reasons.join("; ")}`,
311	      };
312	    }
313	
314	    // 3. Compare assertions
315	    const allAssertionIds = Array.from(
316	      new Set([...Object.keys(currentAssertions), ...Object.keys(baselineAssertions)])
317	    );
318	
319	    if (allAssertionIds.length === 0) {
320	      return {
321	        baselineId: baseline.baselineId,
322	        currentRunId: manifest.runId,
323	        isEligibleForComparison: false,
324	        outcome: "INCONCLUSIVE",
325	        divergences: [],
326	        confidence: 0.0,
327	        explanation: "Neither the run nor the baseline recorded any assertion; an empty comparison proves nothing.",
328	      };
329	    }
330	
331	    const divergences: BaselineComparisonResult["divergences"] = [];
332	    let hasRegression = false;
333	    let hasImprovement = false;
334	    let allCurrentPassed = true;
335	    let allBaselinePassed = true;
336	
337	    for (const id of allAssertionIds) {
338	      const hasCur = Object.prototype.hasOwnProperty.call(currentAssertions, id);
339	      const hasBase = Object.prototype.hasOwnProperty.call(baselineAssertions, id);
340	
341	      // New assertion in current run not present in baseline: do not treat as improvement over baseline
342	      if (!hasBase) {
343	        if (!currentAssertions[id]) {
344	          allCurrentPassed = false;
345	        }
346	        continue;
347	      }
348	
349	      // Assertion present in baseline but omitted from current run: regression in coverage/execution
350	      if (!hasCur) {
351	        allCurrentPassed = false;
352	        hasRegression = true;
353	        divergences.push({
354	          assertionId: id,
355	          baselineStatus: baselineAssertions[id] ? "PASS" : "FAIL",
356	          currentStatus: "FAIL",
357	          details: `Assertion '${id}' was verified in baseline but omitted from current run.`,
358	        });
359	        continue;
360	      }
361	
362	      const cur = currentAssertions[id];
363	      const base = baselineAssertions[id];
364	
365	      if (!cur) allCurrentPassed = false;
366	      if (!base) allBaselinePassed = false;
367	
368	      if (base === true && cur === false) {
369	        hasRegression = true;
370	        divergences.push({
371	          assertionId: id,
372	          baselineStatus: "PASS",
373	          currentStatus: "FAIL",
374	          details: `Assertion '${id}' passed in baseline but failed in current run.`,
375	        });
376	      } else if (base === false && cur === true) {
377	        hasImprovement = true;
378	        divergences.push({
379	          assertionId: id,
380	          baselineStatus: "FAIL",
381	          currentStatus: "PASS",
382	          details: `Assertion '${id}' failed in baseline but passed in current run.`,
383	        });
384	      }
385	    }
386	
387	    // 4. Determine comparative classification
388	    let outcome: ComparativeOutcome;
389	    let explanation: string;
390	
391	    if (options?.isKnownFlaky || (options?.isPriorRegressionCandidate && !hasRegression)) {
392	      outcome = "FLAKY";
393	      explanation =
394	        "Assertion outcome exhibited non-deterministic or intermittent behaviour across runs.";
395	    } else if (hasRegression) {
396	      if (isRepeatReproduction || options?.isPriorRegressionCandidate) {
397	        outcome = "CONFIRMED_REGRESSION";
398	        explanation = `Confirmed reproducible regression across ${divergences.length} assertion(s).`;
399	      } else {
400	        outcome = "REGRESSION_CANDIDATE";
401	        explanation = `Regression candidate detected across ${divergences.length} assertion(s). Requires reproduction run.`;
402	      }
403	    } else if (hasImprovement) {
404	      outcome = "IMPROVEMENT_CANDIDATE";
405	      explanation = `Improvement candidate: ${divergences.length} previously failing assertion(s) now pass.`;
406	    } else if (allCurrentPassed && allBaselinePassed) {
407	      outcome = "PASS";
408	      explanation = "All deterministic assertions pass and match baseline behavior.";
409	    } else {
410	      outcome = "FAIL";
411	      explanation = "Current run failed assertions in identical manner to baseline.";
412	    }
413	
414	    return {
415	      baselineId: baseline.baselineId,
416	      currentRunId: manifest.runId,
417	      isEligibleForComparison: true,
418	      outcome,
419	      divergences,
420	      confidence: 1.0,
421	      explanation,
422	    };
423	  }
424	}
