    const other = { manifest: r1m, assertions: { "a-1": false, "a-2": true } };
    assert.equal(CeriBaselineComparator.compareToVerifiedBaseline(r2.manifest, r2.assertions, vb, { priorRun: other }).outcome, "REGRESSION_CANDIDATE");
