  const need = (ok: boolean, why: string, field: string) => {
    if (!ok) {
      reasons.push(why);
      name(field);
    }
  };
  if (!SHA256_HEX.test(baseline.manifestSha256 ?? "")) unbound("manifestSha256 is not a sha256 hex digest", "manifestSha256");
